evidence.excerpt:
* API:
  - Post /Job/Employer/JobPost -> JobID { Description, NeededSkills, Budget }
  - Patch /Job/Freelancer/Apply { JobID, Proposal }
  - Patch /Job/Employer/SelectFreelancer { FreelancerID, JobID }
  - Post /Freelancer/SendMessage { EmployerID, Message }
  - Post /Employer/SendMessage { FreelancerID, Message }
  - Post /Job/Employer/Contract -> ContractID { JobID, FreelancerID }
  - Patch /Job/Freelancer/AcceptContract { JobID, ContractID, FreelancerID }
  - Patch /Employer/Pay -> PaymentID { FreelancerID, PaymentDetails }
  - Patch /Freelancer/SearchJob { Keyword, Skills, PayRange }
  - Patch /Employer/SearchFreelancer { Expertise, ExperienceLevel, Reviews }
